lab.solution:
graph = {'app': ['a-demo'], 'a-demo': []}

def relationship_status(name):
    if name not in graph:
        return 'unknown'
    if not graph[name]:
        return 'known-empty'
    return 'known-linked'

assert relationship_status('app') == 'known-linked'
assert relationship_status('a-demo') == 'known-empty'
assert relationship_status('missing-demo') == 'unknown'
print('relationship states checked')
